const raw = $input.first().json.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
const parsed = JSON.parse(raw);
const photoData = $('Encode Photo Base64').item.json;
const scenes = Array.isArray(parsed.scenes) && parsed.scenes.length ? parsed.scenes : [
  { badge: 'PROMO', headline: parsed.title || 'Produk Pilihan', subtext: 'Kualitas terbaik hari ini', durationSec: 6, motion: 'zoomIn', imagePrompt: 'Luxury commercial product photography, dramatic studio lighting, no text' }
];

return scenes.map((scene, idx) => ({
  json: {
    sceneIndex: idx,
    totalScenes: scenes.length,
    jobId: photoData.jobId,
    chatId: photoData.chatId,
    productImageBase64: photoData.productImageBase64,
    productImageMimeType: photoData.productImageMimeType,
    title: parsed.title || 'Rekomendasi Produk Pilihan',
    caption: parsed.caption || 'Cek link produk sekarang! #affiliate',
    narration: parsed.narration || 'Produk wajib punya hari ini!',
    scene,
    imagePrompt: scene.imagePrompt || 'Luxury commercial product photography, dramatic studio lighting, no text'
  }
}));

const items = $input.all();
const parsedItems = $('Parse Affiliate Script').all();
const first = parsedItems[0].json;
const scenes = parsedItems.map((p, idx) => {
  const imgPart = items[idx]?.json?.candidates?.[0]?.content?.parts?.find(pt => pt.inlineData)?.inlineData;
  return {
    ...p.json.scene,
    imageBase64: imgPart?.data || '',
    imageMimeType: imgPart?.mimeType || 'image/png'
  };
});
return [{
  json: {
    jobId: first.jobId,
    chatId: first.chatId,
    title: first.title,
    caption: first.caption,
    narration: first.narration,
    productImageBase64: first.productImageBase64,
    productImageMimeType: first.productImageMimeType,
    scenes
  }
}];
